"use strict";(self.webpackChunkbellplay_docs=self.webpackChunkbellplay_docs||[]).push([[92674],{61988:e=>{e.exports=JSON.parse('{"tag":{"label":"importaudio","permalink":"/docs/tags/importaudio","allTagsPath":"/docs/tags","count":20,"items":[{"id":"learn/examples/resynthesis","title":"1. Audio resynthesis","description":"A simple demonstration of granular quasi-resynthesis via partial tracks, where an sound is used to guide the behavior of sinusoidal grains.","permalink":"/docs/learn/examples/resynthesis"},{"id":"learn/examples/audiomosaic","title":"10. Audio mosaicing","description":"An example of basic audio mosaicking in bellplay~, where a target audio file is reconstructed using segments drawn from a small audio corpus.","permalink":"/docs/learn/examples/audiomosaic"},{"id":"learn/tutorials/bufferprocessing","title":"10. Buffer processing","description":"One of the core features of bellplay~ is the ability to dynamically and flexibly apply chains of DSP algorithms to our buffers.","permalink":"/docs/learn/tutorials/bufferprocessing"},{"id":"learn/tutorials/postprocessing","title":"11. Post-rendering processing","description":"Sometimes it can be more useful or desirable to apply processing to the entire output, instead of processing each buffer individually.","permalink":"/docs/learn/tutorials/postprocessing"},{"id":"learn/examples/keymaps","title":"13. Generating keymaps","description":"This example automatically generates a custom keymap given a list of audio file paths:","permalink":"/docs/learn/examples/keymaps"},{"id":"learn/tutorials/bufferinspector","title":"14. Inspecting buffers","description":"An essential part of writing code is being able to debug unwanted or unexpected behaviors.","permalink":"/docs/learn/tutorials/bufferinspector"},{"id":"learn/examples/neuralsynth","title":"14. Neural synthesizer","description":"This tutorial demonstrates how to use a multi-layer perceptron (MLP) neural network","permalink":"/docs/learn/examples/neuralsynth"},{"id":"learn/tutorials/analysis","title":"15. Audio descriptors","description":"One of the core features in bellplay~ is our ability to analyze buffers to extract relevant information.","permalink":"/docs/learn/tutorials/analysis"},{"id":"learn/tutorials/analysismodes","title":"16. Audio descriptor modes","description":"When analyzing buffers, we can specify the output format for many of the available audio descriptors.","permalink":"/docs/learn/tutorials/analysismodes"},{"id":"learn/tutorials/features","title":"17. More audio features","description":"This tutorial provides an additional example for using buffer analysis features for audio processing.","permalink":"/docs/learn/tutorials/features"},{"id":"learn/tutorials/buildcorpus","title":"18. Audio corpora with SQL tables","description":"Some basic familiarity with SQLite3 is expected to fully understand this tutorial.","permalink":"/docs/learn/tutorials/buildcorpus"},{"id":"learn/tutorials/caching","title":"19. Caching data","description":"In bellplay~, computation-heavy operations such as building large corpora, analyzing lots of audio data, and more, can be take a very long time, thus making it more tedious to experiment with our scripts every time we run them.","permalink":"/docs/learn/tutorials/caching"},{"id":"learn/examples/basicgranulation","title":"2. Basic granulation","description":"An example of basic audio granulation, where short audio.","permalink":"/docs/learn/examples/basicgranulation"},{"id":"learn/tutorials/kdtree","title":"24. Feature-driven sampling","description":"This tutorial shows how to build k-dimensional trees to efficiently perform feature-based search on buffers.","permalink":"/docs/learn/tutorials/kdtree"},{"id":"learn/tutorials/sourceseparation","title":"25. Audio source separation","description":"This tutorial demonstrates how to perform rudimentary source separation","permalink":"/docs/learn/tutorials/sourceseparation"},{"id":"learn/tutorials/importingaudio","title":"3. Importing audio","description":"In bellplay~ we can also generate buffers by importing our own audio files into our scripts.","permalink":"/docs/learn/tutorials/importingaudio"},{"id":"learn/examples/waveshaping","title":"5. Waveshaping buffers","description":"A basic example of waveshaping in bellplay~, using a randomly generated breakpoint function.","permalink":"/docs/learn/examples/waveshaping"},{"id":"learn/tutorials/bufferkeys","title":"6. Buffer keys","description":"Buffers in bellplay~ are simply structured lists of key-value pairs.","permalink":"/docs/learn/tutorials/bufferkeys"},{"id":"learn/examples/gliss","title":"6. Glissando texture","description":"An example of using time-varying resampling to generate a polyphonic texture.","permalink":"/docs/learn/examples/gliss"},{"id":"learn/examples/temporalquantization","title":"9. Temporal quantization","description":"A basic example of temporal quantization, where transient-based segments are temporally shifted to align with a rhythmic grid.","permalink":"/docs/learn/examples/temporalquantization"}],"unlisted":false}}')}}]);